import java.time.Instant;
import java.util.List;
import java.util.Optional;

public interface TokenRepository extends JpaRepository<Token, Long> {

    Optional<Token> findByTokenValue(String tokenValue);

    List<Token> findByUserId(String userId);

    List<Token> findByTokenType(Token.TokenType tokenType);

    @Query("SELECT t FROM Token t WHERE t.tokenValue = :tokenValue")
    Optional<Token> findTokenByValue(@Param("tokenValue") String tokenValue);

    @Modifying
    @Transactional
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.tokenValue = :tokenValue AND t.isRevoked = false")
