    @Modifying
    @Transactional
    @Query("UPDATE Token t SET t.isConsumed = true WHERE t.tokenValue = :tokenValue AND t.isConsumed = false")
    int consumeToken(@Param("tokenValue") String tokenValue);

    @Modifying
    @Transactional
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.userId = :userId AND t.tokenType IN ('ACCESS', 'REFRESH', 'ONCE') AND t.isRevoked = false")
    int revokeAllUserTokens(@Param("userId") String userId);

    @Modifying
    @Transactional
    @Query("DELETE FROM Token t WHERE t.expiresAt < :now AND t.isRevoked = false AND t.isConsumed = false")
