package com.auth.service;

import com.auth.model.Token;
import com.auth.model.Token.TokenType;
import com.auth.model.User;
import com.auth.repository.TokenRepository;
import com.auth.repository.UserRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.security.SecureRandom;
import java.time.Instant;
import java.util.Base64;
import java.util.List;
import java.util.Map;
import java.util.UUID;

@Service
public class AuthService {

    private final UserRepository userRepository;
    private final TokenRepository tokenRepository;
    private final SecureRandom random = new SecureRandom();

    // Token lifetimes in milliseconds
    private static final long ACCESS_TOKEN_LIFETIME_MS = 10 * 60 * 1000;   // 10 minutes
    private static final long REFRESH_TOKEN_LIFETIME_MS = 24 * 60 * 60 * 1000; // 24 hours
    private static final long ONCE_TOKEN_LIFETIME_MS = 5 * 60 * 1000;      // 5 minutes

    @Autowired
    public AuthService(UserRepository userRepository, TokenRepository tokenRepository) {
        this.userRepository = userRepository;
        this.tokenRepository = tokenRepository;
    }

    /**
     * Generate a secure random token
     */
    private String generateToken() {
        byte[] bytes = new byte[32];
        random.nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    /**
     * Login - creates user if not exists, issues all three tokens
     */
    @Transactional
    public Map<String, Object> login(String username, String password) {
        // Create user if doesn't exist (accept any non-empty username/password)
        User user = userRepository.findByUsername(username)
            .orElseGet(() -> {
                User newUser = new User();
                newUser.setUsername(username);
                newUser.setPassword(password); // In real app, would hash this
                return userRepository.save(newUser);
            });

        // Generate tokens
        String accessToken = generateToken();
        String refreshToken = generateToken();
        String onceToken = generateToken();
        Instant now = Instant.now();

        // Create Access Token
        Token accessTokenEntity = new Token();
        accessTokenEntity.setTokenValue(accessToken);
        accessTokenEntity.setUserId(user.getUsername());
        accessTokenEntity.setTokenType(TokenType.ACCESS);
        accessTokenEntity.setIssuedAt(now);
        accessTokenEntity.setExpiresAt(now.plusSeconds(ACCESS_TOKEN_LIFETIME_MS / 1000));
        accessTokenEntity.setIsRevoked(false);
        accessTokenEntity.setIsConsumed(false);
        tokenRepository.save(accessTokenEntity);

        // Create Refresh Token
        Token refreshTokenEntity = new Token();
        refreshTokenEntity.setTokenValue(refreshToken);
        refreshTokenEntity.setUserId(user.getUsername());
        refreshTokenEntity.setTokenType(TokenType.REFRESH);
        refreshTokenEntity.setIssuedAt(now);
        refreshTokenEntity.setExpiresAt(now.plusSeconds(REFRESH_TOKEN_LIFETIME_MS / 1000));
        refreshTokenEntity.setIsRevoked(false);
        refreshTokenEntity.setIsConsumed(false);
        tokenRepository.save(refreshTokenEntity);

        // Create One-Time Token
        Token onceTokenEntity = new Token();
        onceTokenEntity.setTokenValue(onceToken);
        onceTokenEntity.setUserId(user.getUsername());
        onceTokenEntity.setTokenType(TokenType.ONCE);
        onceTokenEntity.setIssuedAt(now);
        onceTokenEntity.setExpiresAt(now.plusSeconds(ONCE_TOKEN_LIFETIME_MS / 1000));
        onceTokenEntity.setIsRevoked(false);
        onceTokenEntity.setIsConsumed(false);
        tokenRepository.save(onceTokenEntity);

        return Map.of(
            "accessToken", accessToken,
            "oneTimeToken", onceToken
        );
    }

    /**
     * Logout - revoke all tokens for user
     */
    @Transactional
    public void logout(String accessTokenValue) {
        Token token = tokenRepository.findByTokenValue(accessTokenValue)
            .orElseThrow(() -> new RuntimeException("Invalid access token"));

        // Verify token belongs to a valid user and is not already revoked
        String userId = token.getUserId();
        if (token.getIsRevoked()) {
            throw new RuntimeException("Token already revoked");
        }

        // Revoke all tokens for this user
        tokenRepository.revokeAllUserTokens(userId);
    }
}
