import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.security.SecureRandom;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;

@Service
public class AuthService {

    private final UserRepository userRepository;
    private final TokenRepository tokenRepository;
    private final SecureRandom random = new SecureRandom();

    // Token lifetimes in seconds
    private static final long ACCESS_TOKEN_LIFETIME_SEC = 10 * 60;   // 10 minutes
    private static final long REFRESH_TOKEN_LIFETIME_SEC = 24 * 60 * 60; // 24 hours
    private static final long ONCE_TOKEN_LIFETIME_SEC = 5 * 60;      // 5 minutes

    @Autowired
    public AuthService(UserRepository userRepository, TokenRepository tokenRepository) {
        this.userRepository = userRepository;
        this.tokenRepository = tokenRepository;
    }

    /**
     * Generate a secure random token
     */
    private String generateToken() {
        byte[] bytes = new byte[32];
        random.nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    /**
     * Login - creates user if not exists, issues all three tokens atomically
     */
    @Transactional
    public Map<String, Object> login(String username, String password) {
        // Accept any non-empty username and password
        if (username == null || username.trim().isEmpty() || 
            password == null || password.trim().isEmpty()) {
            throw new IllegalArgumentException("Username and password cannot be empty");
        }

        // Create user if doesn't exist
        User user = userRepository.findByUsername(username)
            .orElseGet(() -> {
                User newUser = new User();
                newUser.setUsername(username);
                newUser.setPassword(password);
                return userRepository.save(newUser);
            });

        // Generate tokens
        String accessToken = generateToken();
        String refreshToken = generateToken();
        String onceToken = generateToken();
        Instant now = Instant.now();

        // Create Access Token (10 min)
        Token accessTokenEntity = new Token();
        accessTokenEntity.setTokenValue(accessToken);
        accessTokenEntity.setUserId(user.getUsername());
        accessTokenEntity.setTokenType(TokenType.ACCESS);
        accessTokenEntity.setIssuedAt(now);
        accessTokenEntity.setExpiresAt(now.plusSeconds(ACCESS_TOKEN_LIFETIME_SEC));
        accessTokenEntity.setIsRevoked(false);
        accessTokenEntity.setIsConsumed(false);
        tokenRepository.save(accessTokenEntity);

        // Create Refresh Token (24 hours)
        Token refreshTokenEntity = new Token();
        refreshTokenEntity.setTokenValue(refreshToken);
        refreshTokenEntity.setUserId(user.getUsername());
        refreshTokenEntity.setTokenType(TokenType.REFRESH);
        refreshTokenEntity.setIssuedAt(now);
        refreshTokenEntity.setExpiresAt(now.plusSeconds(REFRESH_TOKEN_LIFETIME_SEC));
        refreshTokenEntity.setIsRevoked(false);
        refreshTokenEntity.setIsConsumed(false);
        tokenRepository.save(refreshTokenEntity);

        // Create One-Time Token (5 min)
        Token onceTokenEntity = new Token();
        onceTokenEntity.setTokenValue(onceToken);
        onceTokenEntity.setUserId(user.getUsername());
        onceTokenEntity.setTokenType(TokenType.ONCE);
        onceTokenEntity.setIssuedAt(now);
        onceTokenEntity.setExpiresAt(now.plusSeconds(ONCE_TOKEN_LIFETIME_SEC));
        onceTokenEntity.setIsRevoked(false);
        onceTokenEntity.setIsConsumed(false);
        tokenRepository.save(onceTokenEntity);

        return Map.of(
            "accessToken", accessToken,
            "oneTimeToken", onceToken
        );
    }

    /**
     * Renew access token using refresh token with rotation
     * Cookie takes precedence over header
     */
    @Transactional
    public Map<String, Object> renew(String refreshTokenValue) {
        if (refreshTokenValue == null || refreshTokenValue.trim().isEmpty()) {
            throw new IllegalArgumentException("Refresh token required");
        }

        // Find the refresh token
        Optional<Token> tokenOpt = tokenRepository.findByTokenValue(refreshTokenValue);
        if (!tokenOpt.isPresent()) {
            throw new RuntimeException("Invalid refresh token");
        }

        Token refreshToken = tokenOpt.get();

        // Check if token is revoked
        if (refreshToken.getIsRevoked()) {
            throw new RuntimeException("Refresh token revoked");
        }

        // Check if token is consumed (shouldn't happen for refresh tokens but be safe)
        if (refreshToken.getIsConsumed()) {
            throw new RuntimeException("Refresh token already used");
        }

        // Check if token is expired
        if (refreshToken.getExpiresAt().isBefore(Instant.now())) {
            throw new RuntimeException("Refresh token expired");
        }

        // Get user ID
        String userId = refreshToken.getUserId();

        // ATOMIC OPERATION: Revoke old refresh token and create new ones
        // We do this in a single transaction to ensure race-condition safety
        // The key is that we revoke the old token BEFORE inserting the new one

        // First, revoke the current refresh token
        tokenRepository.revokeToken(refreshTokenValue);

        // Generate new tokens
        String newAccessToken = generateToken();
        String newRefreshToken = generateToken();
        Instant now = Instant.now();

        // Create new Access Token (10 min)
        Token newAccessTokenEntity = new Token();
        newAccessTokenEntity.setTokenValue(newAccessToken);
        newAccessTokenEntity.setUserId(userId);
        newAccessTokenEntity.setTokenType(TokenType.ACCESS);
        newAccessTokenEntity.setIssuedAt(now);
        newAccessTokenEntity.setExpiresAt(now.plusSeconds(ACCESS_TOKEN_LIFETIME_SEC));
        newAccessTokenEntity.setIsRevoked(false);
        newAccessTokenEntity.setIsConsumed(false);
        tokenRepository.save(newAccessTokenEntity);

        // Create new Refresh Token (24 hours)
        Token newRefreshTokenEntity = new Token();
        newRefreshTokenEntity.setTokenValue(newRefreshToken);
        newRefreshTokenEntity.setUserId(userId);
        newRefreshTokenEntity.setTokenType(TokenType.REFRESH);
        newRefreshTokenEntity.setIssuedAt(now);
        newRefreshTokenEntity.setExpiresAt(now.plusSeconds(REFRESH_TOKEN_LIFETIME_SEC));
        newRefreshTokenEntity.setIsRevoked(false);
        newRefreshTokenEntity.setIsConsumed(false);
        tokenRepository.save(newRefreshTokenEntity);

        return Map.of(
            "accessToken", newAccessToken
        );
    }

    /**
     * Validate and consume one-time token
     * Exactly one concurrent request can succeed
     */
    @Transactional
    public Map<String, Object> validateToken(String onceTokenValue) {
        if (onceTokenValue == null || onceTokenValue.trim().isEmpty()) {
            throw new IllegalArgumentException("Token required");
        }

        // Find the token
        Optional<Token> tokenOpt = tokenRepository.findByTokenValue(onceTokenValue);
        if (!tokenOpt.isPresent()) {
            throw new RuntimeException("Token not found");
        }

        Token token = tokenOpt.get();

        // Check if already consumed
        if (token.getIsConsumed()) {
            throw new RuntimeException("Token already consumed");
        }

        // Check if revoked
        if (token.getIsRevoked()) {
            throw new RuntimeException("Token revoked");
        }

        // Check if expired
        if (token.getExpiresAt().isBefore(Instant.now())) {
            throw new RuntimeException("Token expired");
        }

        // Check if it's actually a one-time token
        if (token.getTokenType() != TokenType.ONCE) {
            throw new RuntimeException("Invalid token type");
        }

        // Atomically mark as consumed - this is the critical section
        // Using update query to ensure atomicity
        int result = tokenRepository.consumeToken(onceTokenValue);
        if (result == 0) {
            // Race condition: another thread consumed it between our check and update
            throw new RuntimeException("Token already consumed by another request");
        }

        return Map.of(
            "valid", true,
            "message", "Token validated and consumed successfully"
        );
    }

    /**
     * Logout - invalidate all tokens for the user
     */
    @Transactional
    public void logout(String accessTokenValue) {
        if (accessTokenValue == null || accessTokenValue.trim().isEmpty()) {
            throw new IllegalArgumentException("Access token required");
        }

        // Find the access token to verify it belongs to a valid user
        Optional<Token> tokenOpt = tokenRepository.findByTokenValue(accessTokenValue);
        if (!tokenOpt.isPresent()) {
            throw new RuntimeException("Invalid access token");
        }

        Token token = tokenOpt.get();

        // It should be an access token and not already revoked
        if (token.getTokenType() != TokenType.ACCESS) {
            throw new RuntimeException("Invalid token type");
        }

        if (token.getIsRevoked()) {
            throw new RuntimeException("Token already revoked");
        }

        // Get user ID
        String userId = token.getUserId();

        // Revoke all tokens for this user (access, refresh, and one-time)
        tokenRepository.revokeAllUserTokens(userId);
    }
}
