     * Access token renewal
     * POST /api/auth/renew
     * Accepts refreshToken from Cookie (name: refreshToken) OR Header (key: refreshToken)
     * Cookie takes precedence
     * Response body: { "accessToken": "string" }
     * Cookie: refreshToken=<new-token>; HttpOnly
     */
    @PostMapping("/renew")
    public ResponseEntity<?> renew(
            @CookieValue(value = "refreshToken", required = false) String cookieRefreshToken,
            @RequestHeader(value = "refreshToken", required = false) String headerRefreshToken,
            HttpServletResponse response) {

        // Cookie takes precedence over header
        String refreshTokenValue = cookieRefreshToken;
        if (refreshTokenValue == null && headerRefreshToken != null && !headerRefreshToken.trim().isEmpty()) {
            refreshTokenValue = headerRefreshToken;
        }

        if (refreshTokenValue == null || refreshTokenValue.trim().isEmpty()) {
            return ResponseEntity.status(401).body(Map.of("error", "Refresh token missing"));
        }

        try {
            Map<String, String> tokens = authService.renew(refreshTokenValue);

            // Build response with accessToken only
            Map<String, String> responseMap = new HashMap<>();
            responseMap.put("accessToken", tokens.get("accessToken"));

            // Set new Refresh Token as HTTP-only cookie
            Cookie refreshTokenCookie = new Cookie("refreshToken", tokens.get("refreshToken"));
            refreshTokenCookie.setHttpOnly(true);
            refreshTokenCookie.setMaxAge(86400); // 24 hours
            refreshTokenCookie.setPath("/");
            response.addCookie(refreshTokenCookie);

            return ResponseEntity.ok(responseMap);
        } catch (Exception e) {
            // Return 401 for auth errors
            return ResponseEntity.status(401).body(Map.of("error", e.getMessage()));
        }
    }

    /**
     * Logout endpoint
     * POST /api/auth/logout
     * Header: Authorization: Bearer <accessToken>
     * Response: { "message": "Logged out successfully" }
     */
    @PostMapping("/logout")
    public ResponseEntity<?> logout(
            @RequestHeader(value = "Authorization", required = false) String authorizationHeader) {

        if (authorizationHeader == null || !authorizationHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(401).body(Map.of("message", "Invalid or missing Authorization header"));
        }

        // Extract token (remove "Bearer " prefix)
        String accessToken = authorizationHeader.substring(7);

        try {
            authService.logout(accessToken);
            return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
        } catch (Exception e) {
            return ResponseEntity.status(401).body(Map.of("message", e.getMessage()));
        }
    }

    /**
     * Validate one-time token endpoint
     * POST /api/auth/validate-token
     * Request body: { "token": "string" }
     * Response (200): { "valid": true, "message": "..." }
     * Response (401/409): { "valid": false, "message": "..." }
     */
    @PostMapping("/validate-token")
    public ResponseEntity<?> validateToken(@RequestBody Map<String, String> request) {
        if (request == null || !request.containsKey("token")) {
            return ResponseEntity.badRequest().build();
        }

        String token = request.get("token");

        try {
            Map<String, Object> result = authService.validateToken(token);
            return ResponseEntity.ok(result);
        } catch (Exception e) {
            // Return 401 for validation errors
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", e.getMessage()));
        }
    }
}
